module top_module(
  input clk,
  input rst,
  output reg red,
  output reg yellow,
  output reg green
);// Define the states
  parameter Red = 2'b00;
  parameter Red_Yellow = 2'b01;
  parameter Green = 2'b10;
  parameter Yellow = 2'b11;

  // Define the state register and initialize to Red
  reg [1:0] state = Red;

  // Define the state machine
  always @(posedge clk, posedge rst) begin
    if (rst) begin
      state <= Red;
    end else begin
      case (state)
        Red: begin
          red <= 1;
          yellow <= 0;
          green <= 0;
          if (count == 5) begin
            state <= Red_Yellow;
            count <= 0;
          end else begin
            count <= count + 1;
          end
        end
        Red_Yellow: begin
          red <= 1;
          yellow <= 1;
          green <= 0;
          if (count == 2) begin
            state <= Green;
            count <= 0;
          end else begin
            count <= count + 1;
          end
        end
        Green: begin
          red <= 0;
          yellow <= 0;
          green <= 1;
          if (count == 5) begin
            state <= Yellow;
            count <= 0;
          end else begin
            count <= count + 1;
          end
        end
        Yellow: begin
          red <= 0;
          yellow <= 1;
          green <= 0;
          if (count == 2) begin
            state <= Red;
            count <= 0;
          end else begin
            count <= count + 1;
          end
        end
      endcase
    end
  end

  // Define the count register and initialize to 0
  reg [2:0] count = 0;

endmodule

