module top_module(
    input wr_en,
    input wr_clk,
    input rd_clk,
    input [7:0] din,
    input rst,
    input rd_en,
    output reg empty,  // Changed from wire to reg
    output reg full,   // Changed from wire to reg
    output reg [7:0] dout  // Changed from wire to reg
  );// Define the size of the FIFO
  parameter FIFO_SIZE = 256;

  // Create a RAM to store the FIFO data
  reg [7:0] fifo_ram [0:FIFO_SIZE-1];

  // Define pointers to keep track of the read and write positions
  reg [7:0] wr_ptr = 0;
  reg [7:0] rd_ptr = 0;

  // Update the empty and full flags on write and read clock
  always @(posedge wr_clk or posedge rst) begin
    if (rst) begin
      wr_ptr <= 0;
      full <= 0;
    end else if (wr_en && !full) begin
      fifo_ram[wr_ptr] <= din;
      wr_ptr <= (wr_ptr + 1) % FIFO_SIZE;
    end
    // Update empty and full status
    empty <= (wr_ptr == rd_ptr);
    full <= ((wr_ptr + 1) % FIFO_SIZE) == rd_ptr;
  end

  // Define the read operation
  always @(posedge rd_clk or posedge rst) begin
    if (rst) begin
      rd_ptr <= 0;
      dout <= 0; // Initialize dout on reset
    end else if (rd_en && !empty) begin
      dout <= fifo_ram[rd_ptr];
      rd_ptr <= (rd_ptr + 1) % FIFO_SIZE;
    end
  end

endmodule

