    input [7:0] in4,
    input [7:0] in5,
    input [7:0] in6,
    input [7:0] in7,
    output reg [7:0] out0,
    output reg [7:0] out1,
    output reg [7:0] out2,
    output reg [7:0] out3,
    output reg [7:0] out4,
    output reg [7:0] out5,
    output reg [7:0] out6,
    output reg [7:0] out7
);reg [7:0] data[0:7];
integer i, j;
reg [2:0] k;

initial begin
    data[0] = in0;
    data[1] = in1;
    data[2] = in2;
    data[3] = in3;
    data[4] = in4;
    data[5] = in5;
    data[6] = in6;
