description:
Design a 3-to-8 decoder that takes a 9-bit control input and generates a 4-bit output for mode selection. The output, td_mode, maps to specific values based on the three most significant bits of the control signal, where each combination corresponds to a unique 4-bit output representing different modes. This module allows for the controlled activation of different modes based on the provided control input.
module top_module(
  input [8:0] ctrl,
  output reg [3:0] td_mode
);

code:
module top_module(
  input [8:0] ctrl,
  output reg [3:0] td_mode
);wire [2:0] ctrl_bits_for_mux;
  assign ctrl_bits_for_mux = ctrl[7:5];

  always @(*) begin
    case (ctrl_bits_for_mux)
      3'b000: td_mode = 4'b0000;
      3'b001: td_mode = 4'b1000;
      3'b010: td_mode = 4'b0100;
      3'b011: td_mode = 4'b1100;
      3'b100: td_mode = 4'b0010;
      3'b101: td_mode = 4'b1010;
      3'b110: td_mode = 4'b0101;
      3'b111: td_mode = 4'b1111;
    endcase
  end

endmodule

