module top_module(
    input clk,
    input incdec,
    input stop,
	 input rst,
    output [7:0] gray,
	 output [7:0] normal
    );parameter CLK_DIV = 17_000_000;
	reg [31:0] clkDiv = 32'd0;

	reg [7:0] curGray = 8'b0;
	reg [7:0] curNum = 8'b0;

	assign gray = curGray;
	assign normal = curNum;

	always @(posedge clk)
	begin

		clkDiv = clkDiv + 1;


		if (rst == 1) begin
			clkDiv = 0;
			curNum = 8'b0;
		end else if (stop == 1)
			clkDiv = clkDiv - 1;
		else if (clkDiv == CLK_DIV)
		begin

			clkDiv = 0;


			if (incdec == 1) 
				curNum = curNum + 1;
			else
				curNum = curNum - 1;
		end

		curGray = curNum ^ (curNum >> 1);
	end

endmodule

