description:
Design a circuit that functions as an 8-bit analog-to-digital converter (ADC). This module takes a 16-bit analog input voltage signal and converts it to an n-bit digital output, where n is configurable (default is 8 bits). The conversion is performed by comparing the analog input against discrete voltage levels determined by a reference voltage of 5V, allowing the circuit to produce a binary representation of the input voltage. The output will reflect the closest digital value corresponding to the measured analog input.
module top_module(
  input wire [15:0] analog_in,
  output reg [n-1:0] digital_out
);

code:
module top_module(
  input wire [15:0] analog_in,
  output reg [n-1:0] digital_out
);parameter n = 8; // number of bits in digital output signal
parameter vref = 5; // reference voltage for analog input signal

integer i;
reg [15:0] voltage_level;
reg [n-1:0] binary_signal;

always @(*) begin
  for (i = 0; i < (1 << n); i = i + 1) begin
    voltage_level = (vref * i) / ((1 << n) - 1);
    if (analog_in >= voltage_level) begin
      binary_signal = i;
    end
  end
  digital_out = binary_signal;
end

endmodule

