description:
Implement the Verilog module based on the following description.
Module E implements the boolean function z = x ^ y.

// Module F can be described by the following simulation waveform: 

If x = 1, y = 1, then z = 0.
If x = 0, y = 1, then z = 1.
If x = 0, y = 0, then z = 0.
If x = 1, y = 0, then z = 1.

// Now consider a top-level that uses two E submodules and two F submodules. The first input of all four submodules is connect to input 'x', and the second input of all four submodules is connected to 'y'. The output of the first E submodule is connected to a two-input AND, along with the output of the first F submodule. The second pair of E and F submodules is similarly connected to an OR gate. The output of the AND and the OR is connected to an XOR, whose output is 'z'.

// Implement this circuit in Verilog.

module top_module(
    input x,
    input y,
    output z);

code:
module E(
    input x,
    input y,
    output z
);
    assign z = x ^ y;
endmodule

module F(
    input x,
    input y,
    output z
);
    assign z = x ^ y;
endmodule

module top_module(
    input x,
    input y,
    output z
);
    wire e1_out, e2_out, f1_out, f2_out;
    wire and_out, or_out;

    E e1(.x(x), .y(y), .z(e1_out));
    E e2(.x(x), .y(y), .z(e2_out));
    F f1(.x(x), .y(y), .z(f1_out));
    F f2(.x(x), .y(y), .z(f2_out));

    assign and_out = e1_out & f1_out;
    assign or_out = e2_out | f2_out;

    assign z = and_out ^ or_out;
endmodule

