module top_module(lim, CLOCK_50, cout, reset, stay_on);input [27:0]lim;
	input [27:0] stay_on;
	input [0:0]reset;
	input CLOCK_50;
	output cout;
	reg [27:0]count;
	always@(posedge CLOCK_50)
	begin 
		if (reset == 1'b0)
			count <= lim;
		else
			begin

				if (count == 0)
					count <= lim;
				else
					count <= count - 1'b1;
			end
	end

