module piso_32bit
(
    input clk,
    input rst_n,
    input load_en,
    input [31:0] data_in,
    output reg data_out,
    output reg done
);

reg [31:0] shift_reg;
reg [4:0] bit_cnt;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        shift_reg <= 32'd0;
        bit_cnt <= 5'd0;
        data_out <= 1'b0;
        done <= 1'b0;
    end
    else if (load_en) begin
        shift_reg <= data_in;
        bit_cnt <= 5'd32;
        done <= 1'b0;
    end
    else if (bit_cnt > 0) begin
        data_out <= shift_reg[31];
        shift_reg <= shift_reg << 1;
        bit_cnt <= bit_cnt - 1;
        if (bit_cnt == 1) begin
            done <= 1'b1;
        end
    end
    else begin
        data_out <= 1'b0;
        done <= 1'b0;
    end
end

endmodule

