description:
Design a frequency modulation circuit that generates a square wave output. The module takes a clock signal and an active-low reset signal as inputs. It counts clock cycles using a 6-bit register, resetting the count when the reset signal is activated. The output `fm` goes LOW for the first 25 clock cycles and HIGH for the next 25 cycles, creating a frequency that toggles between low and high states at a 50% duty cycle over a total of 50 clock cycles.
module top_module(
		 clk,rst_n,
		 fm
);

code:
module top_module(
		 clk,rst_n,
		 fm
);input clk;
input rst_n;
output fm;

reg[5:0] cnt;

always @ (posedge clk or negedge rst_n)
	if(!rst_n) cnt<=6'd0;
	else if(cnt<6'd49) cnt<=cnt+1'b1;
	else cnt <= 6'd0;

assign fm=(cnt<=6'd24)? 1'b0:1'b1;

endmodule

