module top_module(clk, resetn, sa, dst, opB, opA, op, start, stalled, shift_result, lo, hi);// Inputs
  input clk;
  input resetn;
  input start;
  input [4:0] dst;
  input [31:0] opA;
  input [31:0] opB;
  input [4:0] sa;
  input [2:0] op;

  // Outputs
  output stalled;
  output [31:0] shift_result;
  output [31:0] lo;
  output [31:0] hi;

  // Internal signals
  wire is_signed;
  wire dir;
  wire is_mul;
  wire [32:0] opB_mux_out;
  wire [4:0] left_sa;
  reg [32:0] decoded_sa;
  wire [31:0] result;
  wire or_dst;
  wire start_and_ismul;
  wire request;

  // Control signals
  assign is_mul = op[2];
  assign is_signed = op[1];
  assign dir = op[0];

  // Multiplexer for opB input
  assign opB_mux_out = (is_mul) ? {is_signed & opB[31], opB} : decoded_sa;

  // Replace dummy_mult with a proper multiplication module
  wire [63:0] full_result;
  assign full_result = opA * opB_mux_out[31:0]; // Assuming we need 32-bit multiplication

  // Use appropriate bits from full_result for lo and hi
  assign hi = full_result[63:32];
  assign lo = full_result[31:0];

  // Shift amount decoder
  always @(*) begin
    if (dir == 0) begin
      decoded_sa = {27'b0, sa};
    end else begin
      decoded_sa = {sa, 27'b0};
    end
  end

  // Shift circuit
  assign shift_result = (dir & |sa) ? hi : lo;

  // Stall state machine
  assign or_dst = |dst;
  assign start_and_ismul = start & is_mul;
  assign request = (or_dst & start & ~is_mul) | (start_and_ismul);

  // Replace onecyclestall with a simple implementation
  reg stalled_reg;

  always @(posedge clk or negedge resetn) begin
    if (!resetn)
      stalled_reg <= 1'b0;
    else
      stalled_reg <= request; // Use the request signal for stalling
  end

  assign stalled = stalled_reg;

endmodule

