module top_module(
    input clk,
    input rst,
    input [1:0] op,
    input [31:0] a,
    input [31:0] b,
    input mem_write,
    input [7:0] mem_addr,
    output [31:0] result,
    output mem_read,
    output [31:0] mem_data
);reg [31:0] result_reg;
    reg mem_read_reg;
    reg [31:0] mem_data_reg;
    reg [1:0] op_reg;
    reg [31:0] a_reg;
    reg [31:0] b_reg;
    reg [7:0] mem_addr_reg;
    reg mem_write_reg;

    // Declare memory
    reg [31:0] mem [0:255];  // Memory with 256 locations of 32-bits each

    always @(posedge clk) begin
        if (rst) begin
            result_reg <= 0;
            mem_read_reg <= 0;
            mem_data_reg <= 0;
            op_reg <= 0;
            a_reg <= 0;
            b_reg <= 0;
            mem_addr_reg <= 0;
            mem_write_reg <= 0;
        end else begin
            op_reg <= op;
            a_reg <= a;
            b_reg <= b;
            mem_addr_reg <= mem_addr;
            mem_write_reg <= mem_write;
            mem_read_reg <= 0; // Reset mem_read_reg before following logic

            case (op_reg)
                2'b00: result_reg <= a_reg + b_reg; // Addition
                2'b01: result_reg <= a_reg - b_reg; // Subtraction
                2'b10: result_reg <= a_reg * b_reg; // Multiplication
                2'b11: result_reg <= (b_reg != 0) ? (a_reg / b_reg) : 0; // Division with check
            endcase

            if (mem_write_reg) begin
                mem[mem_addr_reg] <= result_reg;
            end else begin
                mem_read_reg <= 1;
                mem_data_reg <= mem[mem_addr_reg];
            end
        end
    end

    assign result = result_reg;
    assign mem_read = mem_read_reg;
    assign mem_data = mem_data_reg;

endmodule

