                         expected_y1, expected_y2);
                $display("  Got:      y1=%h, y2=%h",
                         y1, y2);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

    // Optional: Waveform dump for debugging
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0,a, clk, reset, y1, y2);
    end

endmodule

description:
Design a 4-bit wide bitwise AND circuit that takes a 4-bit input and performs a logical AND operation with a constant value of 1100. The output will reflect the result of this operation, with each bit of the output determined by the corresponding bit of the input ANDed with the constant.
module top_module(
  input [3:0] in_data,
  output [3:0] out_data
);

code:
module top_module(
  input [3:0] in_data,
  output [3:0] out_data
);parameter const_val = 4'b1100;

  assign out_data = in_data & const_val;

endmodule

module top_module(RESB,O,VIMDS1,VIMDS0);input RESB;
   output O;
   input  VIMDS1,VIMDS0;

   assign RESB = O;   
endmodule

