        test_num = test_num + 1;
        $display("Test Case 005: RESB high, VIMDS mixed");
        RESB = 1'b1;
        VIMDS1 = 1'b0;
        VIMDS0 = 1'b1;
        #1;

        check_outputs(1'b1);
    end
        endtask

    task testcase006;

    begin
        test_num = test_num + 1;
        $display("Test Case 006: RESB low, VIMDS mixed");
        RESB = 1'b0;
        VIMDS1 = 1'b1;
        VIMDS0 = 1'b0;
        #1;

        check_outputs(1'b0);
    end
        endtask

